    const missed=one('.missed h4',box);if(missed&&!one('.title-en',missed))missed.insertAdjacentHTML('beforeend','<span class="title-en" dir="ltr" lang="en">Review These Points</span>');
    all('.missed li',box).forEach(li=>{if(li.dataset.enhanced)return;const question=li.childNodes[0]?.textContent.trim(),itemData=question==='Full employment يعني…'&&box.id==='quiz2'?fullEmploymentChapter:quizEnglish[question];if(itemData){li.dataset.enhanced='1';li.insertAdjacentHTML('beforeend',`<span class="feedback-en" dir="ltr" lang="en"><b>${itemData[0]}</b><br>${itemData[2]}</span>`)}});
